messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Humanoid Treadmill</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
<script type="importmap">
    {
        "imports": {
            "three": "./three.module.js"
        }
    }
</script>
<script type="module">
import * as THREE from './three.module.js';

// --- Configuration ---
const CYCLE_DURATION = 10; // seconds
const STAND_TIME = 2;
const WALK_TIME = 3;
const RUN_TIME = 3;

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x222222);
// Add some fog for depth
scene.fog = new THREE.Fog(0x222222, 10, 50);

const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(5, 3, 5); // Side-on view
camera.lookAt(0, 1, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.3);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 1);
dirLight.position.set(5, 10, 7);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 1024;
dirLight.shadow.mapSize.height = 1024;
scene.add(dirLight);

// --- Materials ---
const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, roughness: 0.5 });
const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366cc, roughness: 0.5 });
const pantsMat = new THREE.MeshStandardMaterial({ color: 0x333333, roughness: 0.5 });
const shoeMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.5 });

// --- Geometry Helpers ---
function createLimb(w, h, d, mat) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return mesh;
}

// --- Humanoid Construction ---
const humanGroup = new THREE.Group();
scene.add(humanGroup);

// Torso (Pivot at top center for arms, center for body)
const torsoGeo = new THREE.BoxGeometry(0.6, 0.9, 0.3);
const torso = new THREE.Mesh(torsoGeo, shirtMat);
torso.position.y = 1.1;
torso.castShadow = true;
humanGroup.add(torso);

// Head
const headGeo = new THREE.BoxGeometry(0.35, 0.35, 0.35);
const head = new THREE.Mesh(headGeo, skinMat);
head.position.y = 1.85;
head.castShadow = true;
humanGroup.add(head);

// Legs (Pivot at hips)
const legGeo = new THREE.BoxGeometry(0.22, 0.85, 0.22);
const shinGeo = new THREE.BoxGeometry(0.2, 0.75, 0.2);
const footGeo = new THREE.BoxGeometry(0.22, 0.15, 0.45);

// Left Leg
const lHip = new THREE.Group();
lHip.position.set(-0.15, 0.68, 0); // Hip height relative to group center
humanGroup.add(lHip);

const lThigh = createLimb(0.22, 0.85, 0.22, pantsMat);
lThigh.position.y = -0.425; // Offset so pivot is at top
lHip.add(lThigh);

const lShin = createLimb(0.2, 0.75, 0.2, pantsMat);
lShin.position.y = -0.85; // Offset for knee pivot
lThigh.add(lShin); // Attach shin to thigh (knee joint)

const lFoot = createLimb(0.22, 0.15, 0.45, shoeMat);
lFoot.position.set(0, -0.85, 0.1); // Offset for ankle pivot
lShin.add(lFoot); // Attach foot to shin

// Right Leg
const rHip = new THREE.Group();
rHip.position.set(0.15, 0.68, 0);
humanGroup.add(rHip);

const rThigh = createLimb(0.22, 0.85, 0.22, pantsMat);
rThigh.position.y = -0.425;
rHip.add(rThigh);

const rShin = createLimb(0.2, 0.75, 0.2, pantsMat);
rShin.position.y = -0.85;
rThigh.add(rShin);

const rFoot = createLimb(0.22, 0.15, 0.45, shoeMat);
rFoot.position.set(0, -0.85, 0.1);
rShin.add(rFoot);

// Arms (Pivot at shoulders)
const armGeo = new THREE.BoxGeometry(0.18, 0.75, 0.18);
const forearmGeo = new THREE.BoxGeometry(0.16, 0.7, 0.16);
const handGeo = new THREE.BoxGeometry(0.16, 0.16, 0.16);

// Left Arm
const lShoulder = new THREE.Group();
lShoulder.position.set(-0.38, 1.45, 0);
humanGroup.add(lShoulder);

const lUpperArm = createLimb(0.18, 0.75, 0.18, shirtMat);
lUpperArm.position.y = -0.375;
lShoulder.add(lUpperArm);

const lElbow = new THREE.Group();
lElbow.position.y = -0.75;
lUpperArm.add(lElbow);

const lForearm = createLimb(0.16, 0.7, 0.16, skinMat);
lForearm.position.y = -0.35;
lElbow.add(lForearm);

const lHand = createLimb(0.16, 0.16, 0.16, skinMat);
lHand.position.y = -0.75;
lForearm.add(lHand);

// Right Arm
const rShoulder = new THREE.Group();
rShoulder.position.set(0.38, 1.45, 0);
humanGroup.add(rShoulder);

const rUpperArm = createLimb(0.18, 0.75, 0.18, shirtMat);
rUpperArm.position.y = -0.375;
rShoulder.add(rUpperArm);

const rElbow = new THREE.Group();
rElbow.position.y = -0.75;
rUpperArm.add(rElbow);

const rForearm = createLimb(0.16, 0.7, 0.16, skinMat);
rForearm.position.y = -0.35;
rElbow.add(rForearm);

const rHand = createLimb(0.16, 0.16, 0.16, skinMat);
rHand.position.y = -0.75;
rForearm.add(rHand);

// --- Treadmill / Ground ---
const groundGeo = new THREE.BoxGeometry(20, 0.5, 10);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x444444 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.position.y = -0.25;
ground.receiveShadow = true;
scene.add(ground);

// Treadmill belt visual
const beltGeo = new THREE.BoxGeometry(2, 0.1, 2);
const beltMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.position.set(0, 0, 0);
belt.receiveShadow = true;
scene.add(belt);

// --- Animation Logic ---

// Helper to get state of the cycle
function getAnimationState(t) {
    // t is time in seconds
    const cyclePos = t % CYCLE_DURATION;

    if (cyclePos < STAND_TIME) return { phase: 'stand', time: cyclePos };
    if (cyclePos < STAND_TIME + WALK_TIME) return { phase: 'walk', time: cyclePos - STAND_TIME };
    if (cyclePos < STAND_TIME + WALK_TIME + RUN_TIME) return { phase: 'run', time: cyclePos - STAND_TIME - WALK_TIME };
    return { phase: 'stand', time: cyclePos - STAND_TIME - WALK_TIME - RUN_TIME };
}

function animateHuman(time) {
    // Reset poses
    let targetHeadRot = 0;
    let targetBodyRot = 0;

    // Frequencies
    // Walk: ~1.5Hz (approx 1.2s cycle -> 0.6s swing)
    // Run: ~3.0Hz (faster, more intensity)

    const phaseTime = time; // time within the current phase

    switch (state.phase) {
        case 'stand':
            // Zero everything
            lHip.rotation.z = 0; rHip.rotation.z = 0;
            lShin.rotation.z = 0; rShin.rotation.z = 0;
            lShoulder.rotation.z = 0; rShoulder.rotation.z = 0;
            lElbow.rotation.z = 0; rElbow.rotation.z = 0;
            lThigh.rotation.z = 0; rThigh.rotation.z = 0;
            lForearm.rotation.z = 0; rForearm.rotation.z = 0;
            humanGroup.rotation.z = 0;
            humanGroup.position.y = 0;
            head.rotation.x = 0;
            break;

        case 'walk':
            // Walking parameters
            const freq = 3.5; // rad/s
            const swing = 0.6; // rad
            const armSwing = 0.3;

            // Side-on: Z rotation is the swing axis
            // Left leg swings forward (neg Z) while right swings back (pos Z)
            lHip.rotation.z = Math.sin(phaseTime * freq) * swing;
            rHip.rotation.z = -Math.sin(phaseTime * freq) * swing;

            // Knee bends when leg swings back
            // Simple approximation: knee bends when leg is moving back
            lShin.rotation.z = Math.max(0, Math.sin(phaseTime * freq + Math.PI) * 1.2);
            rShin.rotation.z = Math.max(0, Math.sin(phaseTime * freq) * 1.2);

            // Arms counter-swing
            lShoulder.rotation.z = -Math.sin(phaseTime * freq) * armSwing;
            rShoulder.rotation.z = Math.sin(phaseTime * freq) * armSwing;

            // Elbows slightly bent
            lElbow.rotation.z = -0.5;
            rElbow.rotation.z = -0.5;

            // Body stays relatively upright, slight bob
            humanGroup.rotation.z = 0;
            humanGroup.position.y = Math.abs(Math.sin(phaseTime * freq * 2)) * 0.05; // Small vertical bob
            break;

        case 'run':
            // Running parameters
            const rFreq = 7.0; // rad/s (faster)
            const rSwing = 1.2; // larger amplitude
            const rArmSwing = 0.8;

            // Forward lean
            targetBodyRot = -0.25; // Radians

            // Legs
            lHip.rotation.z = Math.sin(phaseTime * rFreq) * rSwing;
            rHip.rotation.z = -Math.sin(phaseTime * rFreq) * rSwing;

            // Knees high
            lShin.rotation.z = Math.max(0, Math.sin(phaseTime * rFreq + Math.PI) * 2.0);
            rShin.rotation.z = Math.max(0, Math.sin(phaseTime * rFreq) * 2.0);

            // Arms pump hard
            lShoulder.rotation.z = -Math.sin(phaseTime * rFreq) * rArmSwing;
            rShoulder.rotation.z = Math.sin(phaseTime * rFreq) * rArmSwing;

            // Elbows bent tighter
            lElbow.rotation.z = -1.2;
            rElbow.rotation.z = -1.2;

            // Bobbing is more intense
            humanGroup.position.y = Math.abs(Math.sin(phaseTime * rFreq * 2)) * 0.15;
            break;
    }

    // Apply body rotation (lean)
    humanGroup.rotation.z = targetBodyRot;

    // Head looks forward
    head.rotation.x = 0;
}

// --- Animation Loop ---
const clock = new THREE.Clock();

function animate() {
    requestAnimationFrame(animate);

    const delta = clock.getDelta();
    const elapsed = clock.getElapsedTime();

    state = getAnimationState(elapsed);

    animateHuman(state.time);

    renderer.render(scene, camera);
}

let state = { phase: 'stand', time: 0 };
animate();

// Handle resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

</script>
</body>
</html>
```
